        new Cap(0.08619f, 0.58699f, 0.0f, 0.085f, 0.595f, 0.0f, 0.17358f),
        new Cap(0.085f, 0.595f, 0.0f, 0.089f, 0.901f, 0.0f, 0.1742f),
        new Cap(0.053f, 0.993f, 0.0f, 0.053f, 1.25082f, 0.0f, 0.20822f),
        new Cap(0.053f, 1.25082f, 0.0f, 0.053f, 1.335f, 0.0f, 0.12403f),
